CREATE TYPE public.app_role AS ENUM ('admin', 'user');
CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '' CHECK (length(display_name)<=100), avatar_path text, preferences jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, UPDATE ON public.profiles TO authenticated;
GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY profiles_read_own ON public.profiles FOR SELECT TO authenticated USING (id=auth.uid());
CREATE POLICY profiles_update_own ON public.profiles FOR UPDATE TO authenticated USING (id=auth.uid()) WITH CHECK (id=auth.uid());
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.has_role(_user_id uuid, _role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
REVOKE ALL ON FUNCTION public.has_role(uuid,public.app_role) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.has_role(uuid,public.app_role) TO authenticated,service_role;
CREATE POLICY roles_read_own ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.touch_updated_at() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN NEW.updated_at=now(); RETURN NEW; END $$;
CREATE FUNCTION public.create_user_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,display_name) VALUES(NEW.id,left(coalesce(NEW.raw_user_meta_data->>'display_name',''),100)); RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.create_user_profile() FROM PUBLIC;
CREATE TRIGGER personalize_profile_created AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_user_profile();
CREATE TABLE public.customers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), profile_id uuid REFERENCES public.profiles(id) ON DELETE SET NULL, name text NOT NULL CHECK(length(name) BETWEEN 1 AND 100), email text CHECK(length(email)<=255), phone text CHECK(length(phone)<=30), notes text CHECK(length(notes)<=5000), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.customers TO authenticated,service_role;
ALTER TABLE public.customers ENABLE ROW LEVEL SECURITY;
CREATE POLICY admin_customers ON public.customers TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.categories (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL CHECK(length(name) BETWEEN 1 AND 100), slug text NOT NULL UNIQUE, published boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.categories TO authenticated,service_role;
ALTER TABLE public.categories ENABLE ROW LEVEL SECURITY;
CREATE POLICY admin_categories ON public.categories TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.products (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), category_id uuid REFERENCES public.categories(id) ON DELETE SET NULL, name text NOT NULL CHECK(length(name) BETWEEN 1 AND 200), slug text NOT NULL UNIQUE, description text NOT NULL DEFAULT '' CHECK(length(description)<=10000), price numeric(12,2) NOT NULL DEFAULT 0 CHECK(price>=0), product_type text NOT NULL DEFAULT 'physical' CHECK(product_type IN ('physical','digital')), published boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.products TO authenticated,service_role;
ALTER TABLE public.products ENABLE ROW LEVEL SECURITY;
CREATE POLICY admin_products ON public.products TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.product_media (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), product_id uuid NOT NULL REFERENCES public.products(id) ON DELETE CASCADE, storage_path text NOT NULL, media_type text NOT NULL CHECK(media_type IN ('image','video')), position integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.product_media TO authenticated,service_role;
ALTER TABLE public.product_media ENABLE ROW LEVEL SECURITY;
CREATE POLICY admin_product_media ON public.product_media TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.product_variants (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), product_id uuid NOT NULL REFERENCES public.products(id) ON DELETE CASCADE, name text NOT NULL CHECK(length(name) BETWEEN 1 AND 100), sku text UNIQUE, attributes jsonb NOT NULL DEFAULT '{}', price numeric(12,2) CHECK(price>=0), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.product_variants TO authenticated,service_role;
ALTER TABLE public.product_variants ENABLE ROW LEVEL SECURITY;
CREATE POLICY admin_product_variants ON public.product_variants TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.coupons (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text NOT NULL UNIQUE CHECK(length(code) BETWEEN 1 AND 50), discount_type text NOT NULL CHECK(discount_type IN ('percent','fixed')), discount_value numeric(12,2) NOT NULL CHECK(discount_value>0 AND (discount_type<>'percent' OR discount_value<=100)), starts_at timestamptz, expires_at timestamptz, max_uses integer CHECK(max_uses>0), active boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.coupons TO authenticated,service_role;
ALTER TABLE public.coupons ENABLE ROW LEVEL SECURITY;
CREATE POLICY admin_coupons ON public.coupons TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.orders (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), customer_id uuid NOT NULL REFERENCES public.customers(id), coupon_id uuid REFERENCES public.coupons(id), status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','awaiting_payment','paid','production','completed','cancelled')), total numeric(12,2) NOT NULL DEFAULT 0 CHECK(total>=0), due_at timestamptz, notes text CHECK(length(notes)<=5000), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.orders TO authenticated,service_role;
ALTER TABLE public.orders ENABLE ROW LEVEL SECURITY;
CREATE POLICY admin_orders ON public.orders TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.order_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), order_id uuid NOT NULL REFERENCES public.orders(id) ON DELETE CASCADE, product_id uuid REFERENCES public.products(id), variant_id uuid REFERENCES public.product_variants(id), name text NOT NULL CHECK(length(name)<=200), quantity integer NOT NULL CHECK(quantity>0), unit_price numeric(12,2) NOT NULL CHECK(unit_price>=0), customization jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.order_items TO authenticated,service_role;
ALTER TABLE public.order_items ENABLE ROW LEVEL SECURITY;
CREATE POLICY admin_order_items ON public.order_items TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.payments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), order_id uuid NOT NULL REFERENCES public.orders(id), amount numeric(12,2) NOT NULL CHECK(amount>0), method text NOT NULL DEFAULT 'pix', status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','confirmed','rejected','refunded')), paid_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.payments TO authenticated,service_role;
ALTER TABLE public.payments ENABLE ROW LEVEL SECURITY;
CREATE POLICY admin_payments ON public.payments TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.payment_proofs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), payment_id uuid NOT NULL REFERENCES public.payments(id) ON DELETE CASCADE, storage_path text NOT NULL, uploaded_by uuid REFERENCES public.profiles(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.payment_proofs TO authenticated,service_role;
ALTER TABLE public.payment_proofs ENABLE ROW LEVEL SECURITY;
CREATE POLICY admin_payment_proofs ON public.payment_proofs TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.quotes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), customer_id uuid REFERENCES public.customers(id), order_id uuid REFERENCES public.orders(id), details text NOT NULL CHECK(length(details) BETWEEN 1 AND 10000), amount numeric(12,2) CHECK(amount>=0), status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','sent','accepted','declined')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.quotes TO authenticated,service_role;
ALTER TABLE public.quotes ENABLE ROW LEVEL SECURITY;
CREATE POLICY admin_quotes ON public.quotes TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.banners (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), title text NOT NULL CHECK(length(title)<=200), storage_path text NOT NULL, media_type text NOT NULL CHECK(media_type IN ('image','video')), destination_url text, position integer NOT NULL DEFAULT 0, published boolean NOT NULL DEFAULT false, starts_at timestamptz, ends_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.banners TO authenticated,service_role;
ALTER TABLE public.banners ENABLE ROW LEVEL SECURITY;
CREATE POLICY admin_banners ON public.banners TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.store_settings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), key text NOT NULL UNIQUE CHECK(length(key)<=100), value jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.store_settings TO authenticated,service_role;
ALTER TABLE public.store_settings ENABLE ROW LEVEL SECURITY;
CREATE POLICY admin_store_settings ON public.store_settings TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.invitation_pages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), customer_id uuid NOT NULL REFERENCES public.customers(id), order_id uuid REFERENCES public.orders(id), slug text NOT NULL UNIQUE, title text NOT NULL CHECK(length(title)<=200), event_at timestamptz, content jsonb NOT NULL DEFAULT '{}', status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','published','archived')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.invitation_pages TO authenticated,service_role;
ALTER TABLE public.invitation_pages ENABLE ROW LEVEL SECURITY;
CREATE POLICY admin_invitation_pages ON public.invitation_pages TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.invitation_media (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), invitation_id uuid NOT NULL REFERENCES public.invitation_pages(id) ON DELETE CASCADE, storage_path text NOT NULL, media_type text NOT NULL CHECK(media_type IN ('image','video','audio','document')), position integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.invitation_media TO authenticated,service_role;
ALTER TABLE public.invitation_media ENABLE ROW LEVEL SECURITY;
CREATE POLICY admin_invitation_media ON public.invitation_media TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.rsvp_responses (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), invitation_id uuid NOT NULL REFERENCES public.invitation_pages(id) ON DELETE CASCADE, guest_name text NOT NULL CHECK(length(guest_name) BETWEEN 1 AND 100), attendance text NOT NULL CHECK(attendance IN ('yes','no','maybe')), party_size integer NOT NULL DEFAULT 1 CHECK(party_size BETWEEN 1 AND 100), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.rsvp_responses TO authenticated,service_role;
ALTER TABLE public.rsvp_responses ENABLE ROW LEVEL SECURITY;
CREATE POLICY admin_rsvp_responses ON public.rsvp_responses TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.customer_files (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), customer_id uuid NOT NULL REFERENCES public.customers(id), order_id uuid REFERENCES public.orders(id), storage_path text NOT NULL, original_name text NOT NULL CHECK(length(original_name)<=255), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.customer_files TO authenticated,service_role;
ALTER TABLE public.customer_files ENABLE ROW LEVEL SECURITY;
CREATE POLICY admin_customer_files ON public.customer_files TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['profiles','user_roles','customers','categories','products','product_media','product_variants','coupons','orders','order_items','payments','payment_proofs','quotes','banners','store_settings','invitation_pages','invitation_media','rsvp_responses','customer_files'] LOOP EXECUTE format('CREATE TRIGGER touch_updated BEFORE UPDATE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at()',t); END LOOP; END $$;
CREATE INDEX products_category_idx ON public.products(category_id);
CREATE INDEX orders_customer_idx ON public.orders(customer_id);
CREATE INDEX order_items_order_idx ON public.order_items(order_id);
CREATE INDEX payments_order_idx ON public.payments(order_id);
CREATE INDEX invitation_customer_idx ON public.invitation_pages(customer_id);
CREATE INDEX rsvp_invitation_idx ON public.rsvp_responses(invitation_id);
CREATE FUNCTION public.allowed_platform_file(bucket text, filename text, mime text) RETURNS boolean LANGUAGE sql IMMUTABLE SET search_path=public AS $$ SELECT CASE WHEN bucket='store-public' THEN lower(filename) ~ '\.(png|jpe?g|webp|gif|avif)$' AND mime IN ('image/png','image/jpeg','image/webp','image/gif','image/avif') WHEN bucket IN ('banners-public','products-public') THEN lower(filename) ~ '\.(png|jpe?g|webp|gif|avif|mp4|webm)$' AND mime IN ('image/png','image/jpeg','image/webp','image/gif','image/avif','video/mp4','video/webm') WHEN bucket='invitations-private' THEN lower(filename) ~ '\.(png|jpe?g|webp|gif|avif|mp4|webm|mp3|wav|ogg|pdf)$' AND mime IN ('image/png','image/jpeg','image/webp','image/gif','image/avif','video/mp4','video/webm','audio/mpeg','audio/wav','audio/x-wav','audio/ogg','application/pdf') WHEN bucket IN ('customer-files-private','payment-proofs-private') THEN lower(filename) ~ '\.(png|jpe?g|webp|pdf)$' AND mime IN ('image/png','image/jpeg','image/webp','application/pdf') ELSE false END $$;
CREATE POLICY public_store_files ON storage.objects FOR SELECT TO anon,authenticated USING(bucket_id IN ('store-public','banners-public','products-public'));
CREATE POLICY admin_platform_files_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id IN ('store-public','banners-public','products-public','invitations-private','customer-files-private','payment-proofs-private') AND public.has_role(auth.uid(),'admin'));
CREATE POLICY admin_platform_files_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK(public.has_role(auth.uid(),'admin') AND public.allowed_platform_file(bucket_id,name,metadata->>'mimetype'));
CREATE POLICY admin_platform_files_update ON storage.objects FOR UPDATE TO authenticated USING(bucket_id IN ('store-public','banners-public','products-public','invitations-private','customer-files-private','payment-proofs-private') AND public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin') AND public.allowed_platform_file(bucket_id,name,metadata->>'mimetype'));
CREATE POLICY admin_platform_files_delete ON storage.objects FOR DELETE TO authenticated USING(bucket_id IN ('store-public','banners-public','products-public','invitations-private','customer-files-private','payment-proofs-private') AND public.has_role(auth.uid(),'admin'));
REVOKE ALL ON FUNCTION public.allowed_platform_file(text,text,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.allowed_platform_file(text,text,text) TO authenticated,service_role;